<template><main class="conteos"><header><div><h2>Inventario físico de almacén</h2><p>Expediente SC-2-15. El ajuste SC-2-16 se genera únicamente al cerrar el conteo autorizado.</p></div><label>Finca<select v-model="fincaId" @change="cargar"><option value="">Seleccione</option><option v-for="f in fincas" :key="f.id" :value="f.id">{{f.code}} - {{f.name}}</option></select></label></header>
<section class="card"><h3>Abrir conteo</h3><div class="form"><label>Almacén<select v-model="nuevo.almacenId"><option value="">Seleccione</option><option v-for="a in almacenes" :key="a.id" :value="a.id">{{a.nombre}}</option></select></label><label>Responsable<input v-model.trim="nuevo.responsableConteo"/></label><label>Verificado por<input v-model.trim="nuevo.verificadoPor"/></label><label>Observaciones<input v-model.trim="nuevo.observaciones"/></label></div><button :disabled="!nuevo.almacenId||!nuevo.responsableConteo||creando" @click="abrir">{{creando?'Abriendo...':'Abrir expediente'}}</button></section>
<section v-if="activo" class="card"><div class="heading"><div><h3>{{activo.numero}} · {{activo.almacenNombre}}</h3><p>{{activo.estado}} <span v-if="activo.numeroAjuste">· Ajuste {{activo.numeroAjuste}}</span></p></div><button @click="descargar(activo)">PDF</button></div><table><thead><tr><th>Producto</th><th>Unidad</th><th>Teórico</th><th>Físico</th><th>Diferencia</th><th>Observación</th></tr></thead><tbody><tr v-for="l in activo.lineas" :key="l.id"><td>{{l.productoNombre}}</td><td>{{l.unidadMedida||'—'}}</td><td>{{n(l.existenciaTeorica)}}</td><td><input v-if="activo.estado==='ABIERTO'" v-model.number="conteo[l.id]" min="0" step="0.0001" type="number"/><span v-else>{{n(l.existenciaFisica)}}</span></td><td>{{activo.estado==='CERRADO'?n(l.diferencia):n((conteo[l.id]??0)-l.existenciaTeorica)}}</td><td><input v-if="activo.estado==='ABIERTO'" v-model.trim="obs[l.id]"/><span v-else>{{l.observaciones||'—'}}</span></td></tr></tbody></table><div v-if="activo.estado==='ABIERTO'" class="close"><label>Autoriza el ajuste/cierre<input v-model.trim="autorizado"/></label><label>Observaciones cierre<input v-model.trim="observacionesCierre"/></label><button :disabled="cerrando||!autorizado" @click="cerrar">{{cerrando?'Cerrando...':'Cerrar y emitir ajuste si hay diferencias'}}</button></div></section>
<section class="card"><h3>Expedientes</h3><p v-if="!historial.length">No hay conteos para la finca seleccionada.</p><table v-else><thead><tr><th>No.</th><th>Almacén</th><th>Apertura</th><th>Estado</th><th>Ajuste</th><th></th></tr></thead><tbody><tr v-for="c in historial" :key="c.id"><td>{{c.numero}}</td><td>{{c.almacenNombre}}</td><td>{{fecha(c.fechaApertura)}}</td><td>{{c.estado}}</td><td>{{c.numeroAjuste||'Sin diferencias'}}</td><td><button @click="ver(c.id)">Ver</button><button @click="descargar(c)">PDF</button></td></tr></tbody></table></section></main></template>
<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {notify} from '@/composables/useNotification';import FincaService from '@/services/FincaService';import AlmacenService from '@/services/AlmacenService';import ConteoService,{type ConteoFisico} from '@/services/ConteoFisicoAlmacenService';
const fincaId=ref(''),fincas=ref<any[]>([]),almacenes=ref<any[]>([]),historial=ref<ConteoFisico[]>([]),activo=ref<ConteoFisico|null>(null),creando=ref(false),cerrando=ref(false),autorizado=ref(''),observacionesCierre=ref('');const nuevo=reactive({almacenId:'',responsableConteo:'',verificadoPor:'',observaciones:''}),conteo=reactive<Record<string,number>>({}),obs=reactive<Record<string,string>>({});const n=(x?:number)=>x==null?'—':x.toLocaleString('es-CU',{maximumFractionDigits:4}),fecha=(x?:string)=>x?new Date(x).toLocaleString('es-CU'):'—';
async function cargar(){activo.value=null;almacenes.value=[];historial.value=[];if(!fincaId.value)return;try{const [a,h]=await Promise.all([AlmacenService.obtenerAlmacenesPorFinca(fincaId.value),ConteoService.listar(fincaId.value)]);almacenes.value=(a.data as any).data||a.data||[];historial.value=h.data||[]}catch{notify.error('Error','No se pudieron cargar los conteos físicos.')}}
function preparar(c:ConteoFisico){activo.value=c;for(const k of Object.keys(conteo))delete conteo[k];for(const k of Object.keys(obs))delete obs[k];c.lineas.forEach(l=>{conteo[l.id]=l.existenciaFisica??0;obs[l.id]=l.observaciones||''});autorizado.value='';observacionesCierre.value=''}async function abrir(){creando.value=true;try{const r=await ConteoService.abrir(nuevo);await cargar();await ver(r.data.id);nuevo.almacenId='';nuevo.responsableConteo='';nuevo.verificadoPor='';nuevo.observaciones='';notify.success('Correcto','Expediente de conteo abierto.')}catch(e:any){notify.error('Error',e.response?.data?.message||'No se pudo abrir el conteo.')}finally{creando.value=false}}async function ver(id:string){try{preparar((await ConteoService.detalle(id)).data)}catch{notify.error('Error','No se pudo abrir el detalle.')}}async function cerrar(){if(!activo.value)return;cerrando.value=true;try{await ConteoService.cerrar(activo.value.id,{autorizadoPor:autorizado.value,observaciones:observacionesCierre.value,lineas:activo.value.lineas.map(l=>({lineaId:l.id,cantidadContada:conteo[l.id],observaciones:obs[l.id]}))});await cargar();await ver(activo.value.id);notify.success('Correcto','Conteo cerrado y diferencias documentadas.')}catch(e:any){notify.error('Error',e.response?.data?.message||'No se pudo cerrar el conteo.')}finally{cerrando.value=false}}async function descargar(c:ConteoFisico){try{const r=await ConteoService.pdf(c.id),u=URL.createObjectURL(r.data),a=document.createElement('a');a.href=u;a.download=`SC-2-15-${c.numero}.pdf`;a.click();URL.revokeObjectURL(u)}catch{notify.error('Error','No se pudo descargar el PDF.')}}onMounted(async()=>{try{fincas.value=(await FincaService.getAll()).data||[]}catch{notify.error('Error','No se pudieron cargar las fincas.')}})</script>
<style scoped>.conteos{max-width:1300px;margin:auto;padding:20px}header,.heading{display:flex;justify-content:space-between;gap:16px;align-items:start}.card{background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:18px;margin-top:16px}.form,.close{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin:12px 0}label{display:grid;gap:5px;font-size:.9rem}input,select{padding:8px;border:1px solid #cbd5e1;border-radius:4px}button{margin:3px;padding:8px 12px;border:0;border-radius:4px;background:#2563eb;color:#fff;cursor:pointer}button:disabled{opacity:.55}table{width:100%;border-collapse:collapse;font-size:.9rem}th,td{padding:8px;border-bottom:1px solid #e5e7eb;text-align:left}td input{width:100%;box-sizing:border-box}</style>
